struct PaddedData {
    int x;
    char y;
    long z;

    // offsetof MUST bypass this user-defined overload of &
    PaddedData* operator&() const { return nullptr; }
};

// Compile-time size_t constant calculation
// Requires <cstddef>
const size_t OFFSET_Y = offsetof(PaddedData, y);
const size_t OFFSET_Z = offsetof(PaddedData, z);

// Conceptual C Implementation (often leveraged by compilers)
#define OFFSETOF_CONCEPT(T, M) \
    ((size_t)&(((T*)0)->M))

size_t offset_x_impl = OFFSETOF_CONCEPT(PaddedData, x);
